<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { getCollabArtifacts, getCollabProject, getCollabTaskPrompt, getCollabWorkflow, type CollabArtifact, type CollabProject, type CollabStage } from '../api/collab-projects.api'
import CollabRequirementWorkflow from './CollabRequirementWorkflow.vue'
import CollabRequirementStageConfig from './CollabRequirementStageConfig.vue'
import { getRequirementAsdm, getRequirementAsdmStages, type AsdmRequirementView, type AsdmStageView, type AsdmStagesView } from '../api/collab-groups.api'
const route=useRoute();const router=useRouter();const requirementKey=computed(()=>String(route.params.requirementKey||route.params.projectKey));const project=ref<CollabProject|null>(null);const stages=ref<CollabStage[]>([]);const artifacts=ref<CollabArtifact[]>([]);const asdm=ref<AsdmRequirementView|null>(null);const loading=ref(true);const error=ref('');const promptBusy=ref(false)
function msg(e:unknown){return(e as{response?:{data?:{message?:string}}})?.response?.data?.message||(e as Error)?.message||'请求失败'}
function asdmRows(data:AsdmStagesView|AsdmStageView[]|null){return Array.isArray(data)?data:(data?.stages||data?.items||[])}
async function withAsdmStageStatus(items:CollabStage[], enabled:boolean){if(!enabled)return items;try{const data=await getRequirementAsdmStages(requirementKey.value);const byKey=new Map(asdmRows(data).map(item=>[item.stageKey,item.status]));return items.map(item=>({...item,asdmStatus:byKey.get(item.stageKey)}))}catch{return items}}
async function load(){loading.value=true;error.value='';try{const[p,w,a,d]=await Promise.all([getCollabProject(requirementKey.value),getCollabWorkflow(requirementKey.value),getCollabArtifacts(requirementKey.value),getRequirementAsdm(requirementKey.value)]);project.value=p;stages.value=await withAsdmStageStatus([...w.stages].sort((x,y)=>(x.stageOrder||x.order||0)-(y.stageOrder||y.order||0)),d.enabled);artifacts.value=a;asdm.value=d}catch(e){error.value=msg(e)}finally{loading.value=false}}
function openStage(stageKey:string){router.push({name:'collab-requirement-stage',params:{requirementKey:requirementKey.value,stageKey}})}
async function refreshFromConfig(){try{const[p,w,a,d]=await Promise.all([getCollabProject(requirementKey.value),getCollabWorkflow(requirementKey.value),getCollabArtifacts(requirementKey.value),getRequirementAsdm(requirementKey.value)]);project.value=p;asdm.value=d;stages.value=await withAsdmStageStatus([...w.stages].sort((x,y)=>(x.stageOrder||x.order||0)-(y.stageOrder||y.order||0)),d.enabled);artifacts.value=a}catch(e){error.value=msg(e)}}
const included=computed(()=>stages.value.filter(s=>s.status!=='SKIPPED'));const progress=computed(()=>project.value?.progress??(included.value.length?Math.round(included.value.filter(s=>s.status==='COMPLETED').length/included.value.length*100):0))
async function copyPrompt(stage:CollabStage){promptBusy.value=true;try{const result=await getCollabTaskPrompt(requirementKey.value,stage.stageKey);await navigator.clipboard.writeText(result.prompt);window.alert('阶段任务提示词已复制')}catch(e){error.value=msg(e)}finally{promptBusy.value=false}}
onMounted(load)
</script>

<template><main class="page"><button class="back" @click="project?.groupKey?router.push({name:'collab-group-detail',params:{groupKey:project.groupKey}}):router.push({name:'collab-projects'})">← {{project?.groupName||'项目组'}}</button><div v-if="error" class="error">{{error}} <button @click="error=''">关闭</button></div><div v-if="loading" class="empty">正在加载需求…</div><template v-else-if="project"><header class="hero"><div><span class="eyebrow">REQUIREMENT / {{project.groupName||project.groupKey||'COLLAB'}}</span><h1>{{project.name}}</h1><p>{{project.description||'暂无需求说明'}}</p></div><div class="actions"><button class="secondary" @click="router.push({name:'collab-requirement-history',params:{requirementKey}})">需求历史</button><button class="primary" :disabled="promptBusy||!stages.length||project.status==='COMPLETED'" @click="copyPrompt(stages.find(s=>(s.order??s.stageOrder)===project?.currentStageOrder)||stages[0])">复制当前阶段提示词</button></div></header><section class="summary"><div><small>审批策略</small><b>{{project.approvalLevel}} · {{project.approvalLevel==='L1'?'每阶段审批':project.approvalLevel==='L2'?'继承审批人，按阶段可选':'自动流转'}}</b></div><div><small>模板快照</small><b>v{{project.inheritedTemplateVersion??'—'}}</b></div><div><small>阶段进度</small><b>{{progress}}% · {{included.filter(s=>s.status==='COMPLETED').length}} / {{included.length}}</b></div><div><small>业务代码仓快照</small><a v-if="project.gitlabRootSnapshot" :href="project.gitlabRootSnapshot" target="_blank" rel="noopener">{{project.gitlabRootSnapshot}}</a><b v-else>继承自项目组</b></div></section><section v-if="asdm?.enabled" class="asdm-overview"><div><strong>ASDM 需求分析</strong><span>分支 {{asdm.branch}}</span></div><span class="binding-status">{{asdm.bindingStatus||project.asdmBindingStatus}}</span><span v-if="asdm.requirementPath" class="path">{{asdm.requirementPath}}</span><button @click="openStage('REQUIREMENT')">查看检测详情 →</button></section><CollabRequirementWorkflow :stages="stages" :approval-level="project.approvalLevel" @open-stage="openStage"/><CollabRequirementStageConfig embedded :project-key="requirementKey" @updated="refreshFromConfig" /><section class="panel"><header><div><h2>最近产物</h2><p>产物正文与审批链接按阶段查看。</p></div></header><div v-if="!artifacts.length" class="empty small">需求产物提交后显示在这里。</div><button v-for="a in artifacts.slice(0,8)" :key="a.artifactVersionId" class="artifact" @click="openStage(a.stageKey)"><span>MD</span><strong>{{a.title}}</strong><small>{{a.stageKey}} · v{{a.versionNo}} · 第{{a.attemptNo}}轮</small><b>查看阶段 →</b></button></section></template></main></template>

<style scoped>
.asdm-overview{display:flex;align-items:center;gap:16px;padding:13px 16px;margin:-4px 0 16px;border:1px solid var(--border-accent);border-radius:10px;background:var(--surface-1);font-size:11px}.asdm-overview>div{display:grid;gap:4px}.asdm-overview strong{font-size:12px}.asdm-overview span{color:var(--text-3)}.asdm-overview .path{flex:1;overflow:hidden;text-overflow:ellipsis}.asdm-overview button{border:0;background:none;color:var(--accent-400);cursor:pointer}@media(max-width:850px){.asdm-overview{align-items:flex-start;flex-direction:column}}
.page{max-width:1500px;margin:auto;padding:28px 32px 70px;color:var(--text-1)}.back{border:0;background:none;color:var(--text-2);padding:0 0 20px;cursor:pointer}.hero{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:18px}.eyebrow{font:700 10px var(--font-mono);letter-spacing:.15em;color:var(--accent-400)}h1{margin:7px 0;font-size:30px}.hero p{margin:0;color:var(--text-2)}.actions{display:flex;gap:8px;flex-wrap:wrap}.primary,.secondary{padding:9px 12px;border:0;border-radius:8px;cursor:pointer;font-weight:650}.primary{background:var(--accent-600);color:white}.secondary{background:var(--surface-3);color:var(--text-1)}button:disabled{opacity:.5}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;padding:16px 18px;border:1px solid var(--border-1);border-radius:11px;background:var(--surface-1);margin-bottom:16px}.summary>div{display:grid;gap:6px;min-width:0}.summary small{font-size:10px;color:var(--text-3)}.summary b,.summary a{font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--text-1)}.summary a{color:var(--accent-400)}.panel{padding:16px 18px;border:1px solid var(--border-1);border-radius:12px;background:var(--surface-1);margin-bottom:16px}.panel header{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.panel header>span{font-size:10px;color:var(--text-3)}.panel h2{margin:0 0 5px;font-size:15px}.panel p{margin:0;color:var(--text-3);font-size:11px}.artifact{display:grid;grid-template-columns:34px minmax(100px,1fr) auto auto;align-items:center;gap:10px;width:100%;padding:10px 3px;border:0;border-top:1px solid var(--border-1);background:none;text-align:left;color:var(--text-1);cursor:pointer}.artifact>span{display:grid;place-items:center;width:30px;height:30px;border-radius:7px;background:var(--accent-soft);color:var(--accent-400);font-size:9px}.artifact strong{font-size:12px}.artifact small,.artifact b{font-size:10px;color:var(--text-3)}.artifact b{color:var(--accent-400)}.empty{display:grid;place-items:center;min-height:160px;color:var(--text-3)}.empty.small{min-height:70px}.error{padding:10px;margin-bottom:12px;background:var(--error-soft);color:var(--error);border-radius:8px}.error button{float:right}@media(max-width:850px){.page{padding:22px 14px}.hero{align-items:flex-start;flex-direction:column}.summary{grid-template-columns:1fr 1fr}.artifact{grid-template-columns:30px 1fr auto}.artifact b{display:none}}
</style>
